import{_ as t,o as n,c as s,a2 as a}from"./chunks/framework.CQxpk36T.js";const h=JSON.parse('{"title":"Se connecter à Home Assistant","description":"","frontmatter":{},"headers":[],"relativePath":"home-assistant/index.md","filePath":"home-assistant/index.md","lastUpdated":1793563901000}'),o={name:"home-assistant/index.md"};function i(r,e,l,u,c,d){return n(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="se-connecter-a-home-assistant" tabindex="-1">Se connecter à Home Assistant <a class="header-anchor" href="#se-connecter-a-home-assistant" aria-label="Permalink to &quot;Se connecter à Home Assistant&quot;">​</a></h1><p>HAven parle directement à Home Assistant, depuis le navigateur, par la même connexion WebSocket que l&#39;interface de Home Assistant elle-même. Pas d&#39;intégration à installer, pas de jeton à copier.</p><h2 id="se-connecter" tabindex="-1">Se connecter <a class="header-anchor" href="#se-connecter" aria-label="Permalink to &quot;Se connecter&quot;">​</a></h2><ol><li>Ouvrez les <strong>réglages</strong> (la pastille en haut à droite).</li><li>Saisissez l&#39;<strong>adresse de Home Assistant</strong>, par exemple <code>http://homeassistant.local:8123</code>.</li><li><strong>Se connecter</strong> : la page de connexion habituelle de Home Assistant s&#39;ouvre. Connectez-vous ; vous revenez dans HAven, qui reçoit les états en direct.</li></ol><p>La pastille passe à <strong>Home Assistant</strong>. La connexion est gardée dans le navigateur : les visites suivantes se reconnectent seules. <strong>Se déconnecter</strong> l&#39;oublie et revient au mode démo.</p><div class="tip custom-block"><p class="custom-block-title">Un compte pour la maquette</p><p>Pour une tablette murale ou un téléphone partagé, créez dans Home Assistant un compte dédié (Paramètres → Personnes → Ajouter une personne, avec connexion autorisée) et connectez HAven avec lui.</p></div><h2 id="ce-que-haven-lit" tabindex="-1">Ce que HAven lit <a class="header-anchor" href="#ce-que-haven-lit" aria-label="Permalink to &quot;Ce que HAven lit&quot;">​</a></h2><ul><li>les <strong>états</strong> de toutes les entités, en direct ;</li><li>les <strong>Zones</strong>, <strong>appareils</strong> et <strong>entités</strong> (pour savoir quelle entité est dans quelle pièce) ; HAven suit leurs modifications sans recharger ;</li><li>l&#39;<strong>historique</strong> du jour des capteurs d&#39;énergie (onglet Énergie).</li></ul><p>Et ce qu&#39;il envoie : uniquement les <strong>actions</strong> que vous déclenchez (allumer, régler une consigne, ouvrir une porte…). HAven n&#39;automatise rien et ne modifie pas la configuration de Home Assistant.</p><h2 id="une-connexion-qui-tient" tabindex="-1">Une connexion qui tient <a class="header-anchor" href="#une-connexion-qui-tient" aria-label="Permalink to &quot;Une connexion qui tient&quot;">​</a></h2><p>Sur un téléphone, le navigateur coupe les connexions des pages en arrière-plan. Au retour sur HAven (application rouverte, page de nouveau visible, réseau revenu), la connexion est vérifiée et rétablie aussitôt si elle était tombée : les états sont frais au premier coup d&#39;œil.</p><p>Tant qu&#39;un appareil n&#39;a pas confirmé un ordre, son interrupteur ou son dessin <strong>pulse</strong> doucement ; si rien ne revient au bout de quelques secondes, il reprend son état réel.</p><h2 id="http-ou-https" tabindex="-1">HTTP ou HTTPS <a class="header-anchor" href="#http-ou-https" aria-label="Permalink to &quot;HTTP ou HTTPS&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Pas de mélange</p><p>Si HAven est servi en <strong>HTTPS</strong>, Home Assistant doit l&#39;être aussi : les navigateurs refusent qu&#39;une page sécurisée parle à une adresse en HTTP.</p></div><table tabindex="0"><thead><tr><th>HAven</th><th>Home Assistant</th><th></th></tr></thead><tbody><tr><td><code>http://…</code></td><td><code>http://…</code> ou <code>https://…</code></td><td>✅</td></tr><tr><td><code>https://…</code></td><td><code>https://…</code></td><td>✅</td></tr><tr><td><code>https://…</code></td><td><code>http://…</code></td><td>❌ bloqué par le navigateur</td></tr></tbody></table><p>Sur un réseau privé (Tailscale par exemple), le plus simple est de servir les deux de la même façon. Voir <a href="/HAven-docs/hebergement">Héberger</a>.</p><h2 id="ensuite" tabindex="-1">Ensuite <a class="header-anchor" href="#ensuite" aria-label="Permalink to &quot;Ensuite&quot;">​</a></h2><ul><li><a href="/HAven-docs/home-assistant/correspondances">Ce qui est affiché et piloté</a> : quelle entité fait quoi dans la maquette.</li><li><a href="/HAven-docs/guide/pieces">Pièces et Zones</a> : relier les pièces de la maquette aux Zones.</li></ul>',18)])])}const m=t(o,[["render",i]]);export{h as __pageData,m as default};
